<?php
require_once '../includes/auth.php'; require_role('teacher'); require_once '../config/db.php'; $page_title='Academic Events'; $msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $title=trim($_POST['title']??'');$date=$_POST['date']??'';$desc=trim($_POST['description']??'');if($title&&$date&&$desc){$stmt=$conn->prepare("INSERT INTO tbl_events(title,date,description,created_by) VALUES(?,?,?,?)");$stmt->bind_param("ssss",$title,$date,$desc,$_SESSION['username']);$stmt->execute();$msg='Event added.';}}
$events=$conn->query("SELECT * FROM tbl_events ORDER BY date ASC");require '../includes/header.php'; ?><div class="row g-4"><div class="col-lg-4"><div class="panel"><h5>Add Event</h5><?php if($msg):?><div class="alert alert-success"><?php echo e($msg);?></div><?php endif;?><form method="POST"><input class="form-control mb-2" name="title" placeholder="Event title" required><input class="form-control mb-2" type="date" name="date" required><textarea class="form-control mb-2" name="description" rows="4" placeholder="Description" required></textarea><button class="btn btn-primary w-100">Add Event</button></form></div></div><div class="col-lg-8"><div class="panel"><h5>Academic Calendar</h5><div class="table-responsive mt-3"><table class="table"><thead><tr><th>Date</th><th>Title</th><th>Description</th></tr></thead><tbody><?php while($ev=$events->fetch_assoc()):?><tr><td><?php echo e($ev['date']);?></td><td><?php echo e($ev['title']);?></td><td><?php echo e($ev['description']);?></td></tr><?php endwhile;?></tbody></table></div></div></div></div><?php require '../includes/footer.php'; ?>
